import { db } from "@/lib/db";

export async function GET(request: Request) {
  const { q } = new URL(request.url);
  const { title, telescopeId } = new URLSearchParams(request.url).get("q") || {};

  const exposures = await db.exposure.findMany({
    where: {
      title: {
        contains: q,
        mode: "insensitive",
      },
    },
    include: {
      telescope: true,
    },
  });

  return new Response(JSON.stringify({ exposures, total: exposures.length }), {
    status: 200,
  });
}

